specimens.css:
/* 状态模拟：:hover 无法静态触发，以下三条是 DisclosureRow.module.css 中 .row:hover 相关规则的原样副本。 */
.row.forceHover { color: var(--dsw-alias-label-secondary); }
.row.forceHover .iconIdle { opacity: 0; }
.row.forceHover .chevronHover { opacity: 1; }

/* 静态快照：backdrop 真实渲染是覆盖全视口的 position: fixed 门户；这里收进示例框内。 */
.backdrop.snapshotStatic { position: relative; inset: auto; width: 100%; height: 300px; }
/* 状态模拟：:focus-visible 无法静态触发，下面是 ImageLightbox.module.css 中 .close:focus-visible 的原样副本。 */
.close.forceFocus { outline: var(--dsw-focus-ring-width) solid var(--dsw-focus-ring-color, var(--dsw-alias-state-business-primary)); outline-offset: 3px; }
